//! Differential tests: the Rust domain must reproduce what the TypeScript protocol produced
//! (`docs/file-vectors.json`, generated by `packages/protocol/scripts/gen-file-vectors.ts`).
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use privcord_domain::{
    channel::normalize_channel_name,
    codec,
    files::{
        file_chunks, sanitize_file_name, sanitize_mime, AssembleResult, BeginOutcome,
        FileAssembler, FileChunk, FileOffer,
    },
    ids::MessageId,
    message::{ChatMessage, ReplyRef},
    network::{encode_turn_share, parse_turn_share, TURN_SHARE_PREFIX},
    privacy::{accepts_direct, can_start_direct, ContactTrust},
    social::{
        delete_frame, parse_delete_frame, parse_react_frame, react_frame, summarize_reactions,
    },
};
use serde_json::Value;
use std::collections::BTreeMap;

fn vectors() -> Value {
    let root = env!("CARGO_MANIFEST_DIR");
    let text = std::fs::read_to_string(format!("{root}/../../docs/file-vectors.json"))
        .expect("file-vectors.json");
    serde_json::from_str(&text).unwrap()
}

#[test]
fn file_offer_and_chunks_match_typescript() {
    let v = vectors();
    let file = &v["file"];
    let offer = FileOffer::from_frame(&file["offer"]).expect("TypeScript offer parses");
    assert_eq!(offer.size, file["size"].as_u64().unwrap() as usize);
    assert_eq!(offer.name, "Report .._final_.pdf");
    // Our own frame is the same JSON value as the TypeScript one.
    assert_eq!(offer.to_frame(), file["offer"]);

    // Rebuild the bytes from the vector's chunks, then re-chunk them: identical frames.
    let mut assembler = FileAssembler::new();
    assert_eq!(assembler.begin(offer.clone()), BeginOutcome::Ok);
    let mut bytes = Vec::new();
    let mut result = AssembleResult::More;
    for c in file["chunks"].as_array().unwrap() {
        let chunk = FileChunk::from_frame(c).expect("chunk parses");
        bytes.extend(codec::decode(&chunk.data).unwrap());
        result = assembler.chunk(&chunk);
    }
    match result {
        AssembleResult::Done {
            offer: done,
            bytes: assembled,
        } => {
            assert_eq!(*done, offer);
            assert_eq!(assembled, bytes);
        }
        other => panic!("expected Done, got {other:?}"),
    }
    let id = MessageId::new("file-vector-1").unwrap();
    let rechunked: Vec<Value> = file_chunks(&id, &bytes).map(|c| c.to_frame()).collect();
    assert_eq!(rechunked, *file["chunks"].as_array().unwrap());
    // The hash TypeScript computed is the hash of those bytes.
    let remade = FileOffer::make(
        id,
        Some("group-xyz".into()),
        "Report .._final_.pdf",
        "application/pdf",
        &bytes,
        1_700_000_000_000,
        offer.reply_to.clone(),
    )
    .unwrap();
    assert_eq!(remade.sha256, offer.sha256);
}

#[test]
fn sanitising_matches_typescript() {
    let v = vectors();
    for pair in v["sanitizeNames"].as_array().unwrap() {
        let (raw, expected) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
        assert_eq!(sanitize_file_name(raw), expected, "name {raw:?}");
    }
    for pair in v["sanitizeMimes"].as_array().unwrap() {
        let (raw, expected) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
        assert_eq!(sanitize_mime(raw), expected, "mime {raw:?}");
    }
}

#[test]
fn reply_frame_matches_typescript() {
    let v = vectors();
    let frame = &v["reply"]["frame"];
    let m = ChatMessage::from_peer_frame(frame).expect("reply frame parses");
    assert_eq!(
        m.reply_to.as_ref().unwrap().preview,
        v["reply"]["preview"].as_str().unwrap()
    );
    assert_eq!(m.to_peer_frame()["replyTo"], frame["replyTo"]);
    // The preview is cut at 120 code points, never mid-character.
    let long = "é".repeat(500);
    let r = ReplyRef::quoting(
        &MessageId::new("a").unwrap(),
        &privcord_domain::UserId::new("u").unwrap(),
        &long,
    );
    assert_eq!(r.preview.chars().count(), 120);
}

#[test]
fn privacy_table_matches_typescript() {
    let v = vectors();
    for row in v["privacy"].as_array().unwrap() {
        let trust = if row["trust"] == "verified" {
            ContactTrust::Verified
        } else {
            ContactTrust::Introduced
        };
        let mine = row["mine"].as_bool().unwrap();
        let peer = row["peer"].as_bool();
        assert_eq!(
            can_start_direct(trust, mine, peer),
            row["canStart"].as_bool().unwrap(),
            "{row}"
        );
        assert_eq!(
            accepts_direct(trust, mine),
            row["accepts"].as_bool().unwrap(),
            "{row}"
        );
    }
}

#[test]
fn social_frames_match_typescript() {
    let v = vectors();
    let s = &v["social"];
    let id = MessageId::new("m-1").unwrap();
    assert_eq!(react_frame(&id, "👍", true), s["react"]);
    assert_eq!(delete_frame(&MessageId::new("m-2").unwrap()), s["del"]);
    assert!(parse_react_frame(&s["react"]).is_some());
    assert_eq!(parse_delete_frame(&s["del"]).unwrap().as_str(), "m-2");
    let mut reactions = BTreeMap::new();
    reactions.insert("a".to_owned(), "👍".to_owned());
    reactions.insert("b".to_owned(), "👍".to_owned());
    reactions.insert("me".to_owned(), "❤️".to_owned());
    let chips: Vec<Value> = summarize_reactions(&reactions, "me")
        .into_iter()
        .map(|c| serde_json::json!({ "emoji": c.emoji, "count": c.count, "mine": c.mine }))
        .collect();
    assert_eq!(Value::Array(chips), s["chips"]);
    // An emoji that is not in the fixed set is refused.
    let mut bad = s["react"].clone();
    bad["emoji"] = "💩".into();
    assert!(parse_react_frame(&bad).is_none());
}

#[test]
fn relay_setup_line_matches_typescript() {
    let v = vectors();
    let line = v["turnShare"].as_str().unwrap();
    assert!(line.starts_with(TURN_SHARE_PREFIX));
    let t = parse_turn_share(line).expect("TypeScript line parses");
    assert_eq!(t.credential, "pä$$ w0rd");
    assert_eq!(encode_turn_share(&t), line);
    assert!(parse_turn_share("hello").is_none());
    assert!(parse_turn_share(&format!("{TURN_SHARE_PREFIX}!!!")).is_none());
}

#[test]
fn channel_names_normalise_like_typescript() {
    assert_eq!(
        normalize_channel_name("#General").as_deref(),
        Some("general")
    );
    assert_eq!(
        normalize_channel_name("  general  ").as_deref(),
        Some("general")
    );
    assert_eq!(
        normalize_channel_name("Lagos Traffic!!").as_deref(),
        Some("lagos-traffic")
    );
    assert_eq!(normalize_channel_name("кофе").as_deref(), Some("кофе"));
    assert_eq!(normalize_channel_name("###"), None);
    assert_eq!(normalize_channel_name(""), None);
    assert_eq!(normalize_channel_name(&"x".repeat(100)).unwrap().len(), 32);
    // The vector's own channel name.
    assert_eq!(
        normalize_channel_name(vectors()["channel"]["name"].as_str().unwrap()).as_deref(),
        Some("general")
    );
}

#[test]
fn liveness_and_receipt_frames_parse_like_typescript() {
    use privcord_domain::peer::PeerFrame;
    let root = env!("CARGO_MANIFEST_DIR");
    let v: Value = serde_json::from_str(
        &std::fs::read_to_string(format!("{root}/../../docs/peerauth-vectors.json")).unwrap(),
    )
    .unwrap();
    for o in v["other"].as_array().unwrap() {
        let parsed = PeerFrame::parse(&o["frame"]).expect("parses");
        assert_eq!(parsed.to_value(), o["frame"], "round trip");
        assert!(!o["parsed"].is_null());
    }
    for r in v["rejected"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|r| r["frame"]["kind"] == "ack")
    {
        assert!(PeerFrame::parse(&r["frame"]).is_none() && r["parsed"].is_null());
    }
}
